-- Reports read only TradeDesk records (2026-11-25).
-- Applied to production via MCP as migrations `jobs_completed_date` and `reports_tradedesk_only`.
--
-- 1. jobs.completed_date: entered by hand on the job card (date picker). Admin-only (guard_job_columns).
--    Seeded once from the Completion Log / stage history: batch `completed_date_seed_2026-11-25`
--    in reconciliation_changes (189 jobs; old_date/new_date per job, so it can be undone).
-- 2. job_completion_dates() returns jobs.completed_date only.
-- 3. report_balances_owed(): collected = TradeDesk client payments only (no Completion Log).
-- 4. New: report_job_profitability(p_from, p_to), report_backlog(), report_vendor_owed().
-- 5. report_monthly_scorecard(): every measure bounded to [p_from, p_to] by day.

alter table public.jobs add column if not exists completed_date date;
comment on column public.jobs.completed_date is 'Date the job was completed. Entered by hand on the job card (date picker); TradeDesk reports read only this. Seeded once on 2026-11-25 from the Completion Log / stage history (batch completed_date_seed_2026-11-25).';
alter table public.reconciliation_changes drop constraint reconciliation_changes_kind_check;
alter table public.reconciliation_changes add constraint reconciliation_changes_kind_check check (kind = any (array['contract','payment','signed_date','trade','ghl_project_type','job_created','status','flag','link','job_type','completed_date']));
do $d$ begin execute replace(replace(pg_get_functiondef('public.guard_job_columns'::regproc), 'new.paid_status, new.job_type)', 'new.paid_status, new.job_type, new.completed_date)'), 'old.paid_status, old.job_type)', 'old.paid_status, old.job_type, old.completed_date)'); end $d$;

create or replace function public.job_completion_dates() returns table(job_id uuid, completed_at timestamptz) language sql stable security definer set search_path to 'public' as $f$ select j.id, (j.completed_date::timestamp at time zone 'America/New_York') from public.jobs j where j.completed_date is not null and public.is_admin() $f$;

create or replace function public.report_balances_owed() returns jsonb language plpgsql stable security definer set search_path to 'public' as $f$ declare v jsonb; begin if not public.is_admin() then raise exception 'reports are office-only' using errcode = '42501'; end if; with live as (select * from public.jobs where coalesce(ghl_status, '') not in ('lost', 'abandoned')), td as (select job_id, sum(amount) paid, max(payment_date) last_paid, count(*) n from public.client_payments group by job_id), cr as (select job_id, sum(amount) credited, count(*) n from public.client_credits group by job_id), x as (select l.id job_id, l.number, l.ghl_project_display_id project_ref, l.customer_name customer, l.customer_address address, l.trade, l.job_type, l.stage, coalesce(s.label, l.stage) stage_label, coalesce(s.is_complete, false) finished, coalesce(l.flag, '') = 'on_hold' on_hold, coalesce(l.contract_amount, 0) contract, coalesce(cr.credited, 0) client_credited, coalesce(cr.n, 0) client_credits_count, coalesce(td.paid, 0) collected, coalesce(td.n, 0) payments_count, td.last_paid, l.completed_date from live l left join public.job_stages s on s.key = l.stage left join td on td.job_id = l.id left join cr on cr.job_id = l.id) select jsonb_build_object('generated_at', now(), 'client_credited_total', (select coalesce(sum(client_credited), 0) from x), 'rows', coalesce((select jsonb_agg(to_jsonb(x) || jsonb_build_object('balance', x.contract - x.collected - x.client_credited, 'days_since_complete', case when x.completed_date is not null then (now() at time zone 'America/New_York')::date - x.completed_date end) order by (x.contract - x.collected - x.client_credited) desc) from x), '[]'::jsonb)) into v; return v; end $f$;

create or replace function public.report_job_profitability(p_from date default null, p_to date default null) returns jsonb language plpgsql stable security definer set search_path to 'public' as $f$ declare v_from date := coalesce(p_from, date_trunc('year', now() at time zone 'America/New_York')::date); v_to date := coalesce(p_to, (now() at time zone 'America/New_York')::date); v jsonb; begin if not public.is_admin() then raise exception 'reports are office-only' using errcode = '42501'; end if; if v_to < v_from then raise exception 'report end is before its start' using errcode = '22023'; end if; with fin as (select distinct on (job_id) * from public.job_finalizations order by job_id, seq desc), x as (select j.id job_id, j.number, j.ghl_project_display_id project_ref, j.customer_name customer, j.job_type, j.trade, j.completed_date, coalesce(j.contract_amount, 0) contract, jf.client_credits, coalesce(f.contract_amount, jf.net_contract, 0) revenue, coalesce(f.vendor_total, jf.vendor_total, 0) vendor_cost, coalesce(f.margin, jf.margin, 0) gp, coalesce(f.margin_pct, jf.margin_pct) gp_pct, f.job_id is not null finalized, coalesce(jf.vendor_gross, 0) > 0 has_costs, jf.balance_due from public.jobs j join public.job_financials jf on jf.job_id = j.id left join fin f on f.job_id = j.id where coalesce(j.ghl_status, '') not in ('lost', 'abandoned') and j.completed_date between v_from and v_to) select jsonb_build_object('from', v_from, 'to', v_to, 'generated_at', now(), 'rows', coalesce((select jsonb_agg(to_jsonb(x) order by x.has_costs desc, x.gp_pct asc nulls last) from x), '[]'::jsonb)) into v; return v; end $f$;

create or replace function public.report_backlog() returns jsonb language plpgsql stable security definer set search_path to 'public' as $f$ declare v jsonb; v_today date := (now() at time zone 'America/New_York')::date; begin if not public.is_admin() then raise exception 'reports are office-only' using errcode = '42501'; end if; with x as (select j.id job_id, j.number, j.ghl_project_display_id project_ref, j.customer_name customer, j.job_type, j.trade, j.stage, coalesce(s.label, j.stage) stage_label, coalesce(j.flag, '') = 'on_hold' on_hold, j.contract_signed_date, case when j.contract_signed_date is not null then v_today - j.contract_signed_date end days_since_signed, coalesce(jf.net_contract, 0) contract, coalesce(jf.client_received, 0) collected, coalesce(jf.balance_due, 0) left_to_collect, coalesce(jf.vendor_total, 0) vendor_cost from public.jobs j join public.job_financials jf on jf.job_id = j.id left join public.job_stages s on s.key = j.stage where coalesce(j.ghl_status, '') not in ('lost', 'abandoned') and not coalesce(s.is_complete, false)) select jsonb_build_object('generated_at', now(), 'rows', coalesce((select jsonb_agg(to_jsonb(x) order by x.contract_signed_date nulls last, x.number) from x), '[]'::jsonb)) into v; return v; end $f$;

create or replace function public.report_vendor_owed() returns jsonb language plpgsql stable security definer set search_path to 'public' as $f$ declare v jsonb; v_today date := (now() at time zone 'America/New_York')::date; begin if not public.is_admin() then raise exception 'reports are office-only' using errcode = '42501'; end if; with cr as (select vendor_payment_id, sum(amount) credited from public.vendor_credits where settlement = 'open_bill' and vendor_payment_id is not null group by vendor_payment_id), x as (select p.id payment_id, coalesce(nullif(p.vendor_name, ''), '(no vendor)') vendor, p.category, p.job_id, j.number, j.customer_name customer, j.job_type, coalesce(j.ghl_status, '') in ('lost', 'abandoned') job_lost, p.amount, coalesce(cr.credited, 0) credited, p.amount - coalesce(cr.credited, 0) owed, (p.payment_date at time zone 'America/New_York')::date bill_date, case when p.payment_date is not null then v_today - (p.payment_date at time zone 'America/New_York')::date end days_old, p.note from public.vendor_payments p join public.jobs j on j.id = p.job_id left join cr on cr.vendor_payment_id = p.id where p.status = 'pending') select jsonb_build_object('generated_at', now(), 'rows', coalesce((select jsonb_agg(to_jsonb(x) order by x.vendor, x.days_old desc nulls last) from x where x.owed > 0.005), '[]'::jsonb)) into v; return v; end $f$;

revoke execute on function public.report_job_profitability(date, date), public.report_backlog(), public.report_vendor_owed() from anon;
grant execute on function public.report_job_profitability(date, date), public.report_backlog(), public.report_vendor_owed() to authenticated;

do $d$ declare s text := pg_get_functiondef('public.report_monthly_scorecard(date,date)'::regprocedure); begin s := replace(s, 'from live where date_trunc(''month'', contract_signed_date)::date = mo.m)', 'from live where date_trunc(''month'', contract_signed_date)::date = mo.m and contract_signed_date between v_from and v_to)'); s := replace(s, 'from public.client_payments where payment_date is not null)', 'from public.client_payments where payment_date is not null and (payment_date at time zone ''America/New_York'')::date between v_from and v_to)'); s := replace(s, 'where date_trunc(''month'', c.completed_at at time zone ''America/New_York'')::date = mo.m)', 'where date_trunc(''month'', c.completed_at at time zone ''America/New_York'')::date = mo.m and (c.completed_at at time zone ''America/New_York'')::date between v_from and v_to)'); s := replace(s, 'join live l on l.id = f.job_id), prov as', 'join live l on l.id = f.job_id where (f.finalized_at at time zone ''America/New_York'')::date between v_from and v_to), prov as'); execute s; end $d$;
